import{_ as o,c as t,o as i,ae as r}from"./chunks/framework.CliRSA9F.js";const g=JSON.parse('{"title":"Troubleshooting & Common Issues","description":"","frontmatter":{},"headers":[],"relativePath":"more/troubleshooting.md","filePath":"more/troubleshooting.md"}'),n={name:"more/troubleshooting.md"};function a(s,e,l,u,d,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting &amp; Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting &amp; Common Issues&quot;">​</a></h1><p>This document contains answers to common user questions and troubleshooting steps for PodSEO features. These questions and answers are optimized for chatbot search and resolution.</p><h2 id="keywords-not-appearing-in-keyword-tracker" tabindex="-1">Keywords Not Appearing in Keyword Tracker <a class="header-anchor" href="#keywords-not-appearing-in-keyword-tracker" aria-label="Permalink to &quot;Keywords Not Appearing in Keyword Tracker&quot;">​</a></h2><h3 id="problem-when-i-select-keywords-from-my-list-i-don-t-see-them-in-the-keyword-tracker" tabindex="-1">Problem: &quot;When I select keywords from my list I don&#39;t see them in the keyword tracker&quot; <a class="header-anchor" href="#problem-when-i-select-keywords-from-my-list-i-don-t-see-them-in-the-keyword-tracker" aria-label="Permalink to &quot;Problem: &quot;When I select keywords from my list I don&#39;t see them in the keyword tracker&quot;&quot;">​</a></h3><p><strong>Root Cause</strong>: Keywords only appear in the Keyword Tracker after you explicitly add them to your tracked list. Viewing or selecting a keyword elsewhere (for example in Show Visibility or Competitive Analysis) does not track it.</p><p><strong>Solution — two ways to add a keyword</strong>:</p><p><em>From Keyword Strategy (recommended when you also want to set the tier):</em></p><ol><li>Go to <a href="/features/keyword-strategy.html">Keyword Strategy</a></li><li>Find the keywords you want to track</li><li>Click the <strong>&quot;Add&quot;</strong> button next to each keyword you want to monitor</li><li>Choose the keyword type: Primary (max 3), Secondary, or Monitored (no per-type limit, but all tracked keywords count towards your plan&#39;s total allowance)</li><li>The keywords will now appear in <a href="/features/keyword-tracker.html">Keyword Tracker</a> with performance data</li></ol><p><em>Directly in Keyword Tracker:</em></p><ol><li>Open <a href="/features/keyword-tracker.html">Keyword Tracker</a></li><li>Type the keyword into the <strong>&quot;Add keyword&quot;</strong> field at the top of the page and click <strong>Add</strong></li><li>The keyword is tracked immediately; you can change its tier later in Keyword Strategy</li></ol><p><strong>Key Understanding</strong>:</p><ul><li><strong>Keyword Strategy</strong> = Where you manage tiers (Primary / Secondary / Monitored) and discover keywords to add</li><li><strong>Keyword Tracker</strong> = Where you view performance of tracked keywords, and where you can also quickly add one</li><li>Simply viewing or selecting keywords elsewhere does not automatically track them</li></ul><p><strong>If keywords still don&#39;t appear after adding them</strong>:</p><ul><li>Refresh the page</li><li>Data may take a short time to appear</li><li>Check if you&#39;re viewing the correct platform filter in Keyword Tracker</li><li>Verify you haven&#39;t exceeded your plan&#39;s keyword limits</li></ul><p><strong>Related Questions</strong>:</p><ul><li>&quot;Keywords not showing in tracker&quot;</li><li>&quot;How to add keywords to tracking&quot;</li><li>&quot;I added keywords but don&#39;t see them&quot;</li><li>&quot;Keywords missing from keyword tracker&quot;</li><li>&quot;Selected keywords not tracked&quot;</li></ul><h3 id="problem-my-keywords-show-no-ranking-data-in-the-tracker" tabindex="-1">Problem: &quot;My keywords show no ranking data in the tracker&quot; <a class="header-anchor" href="#problem-my-keywords-show-no-ranking-data-in-the-tracker" aria-label="Permalink to &quot;Problem: &quot;My keywords show no ranking data in the tracker&quot;&quot;">​</a></h3><p><strong>Root Cause</strong>: Either data hasn&#39;t appeared yet, platform filter issues, or keywords with no current rankings.</p><p><strong>Solution</strong>:</p><ol><li><strong>Give It a Moment</strong>: Data may take a short time to appear after adding keywords</li><li><strong>Verify Platform Filters</strong>: Ensure you&#39;re viewing the correct platform (Spotify, Apple Podcasts, etc.) in Keyword Tracker</li><li><strong>Check Keyword Performance</strong>: Some keywords may not have rankings yet - this is normal for new or highly competitive terms</li><li><strong>Review Time Interval</strong>: Adjust the time period filter to see if data exists for different date ranges</li></ol><p><strong>If problem persists</strong>:</p><ul><li>Contact support via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Account Settings &gt; Contact</a></li><li>Provide specific keywords and timeframes for faster resolution</li></ul><h2 id="understanding-feature-relationships" tabindex="-1">Understanding Feature Relationships <a class="header-anchor" href="#understanding-feature-relationships" aria-label="Permalink to &quot;Understanding Feature Relationships&quot;">​</a></h2><h3 id="problem-i-m-confused-about-how-keyword-strategy-and-keyword-tracker-work-together" tabindex="-1">Problem: &quot;I&#39;m confused about how Keyword Strategy and Keyword Tracker work together&quot; <a class="header-anchor" href="#problem-i-m-confused-about-how-keyword-strategy-and-keyword-tracker-work-together" aria-label="Permalink to &quot;Problem: &quot;I&#39;m confused about how Keyword Strategy and Keyword Tracker work together&quot;&quot;">​</a></h3><p><strong>Solution</strong>:</p><ul><li><p><strong>Keyword Strategy</strong>: Your keyword management center where you:</p><ul><li>Discover new keywords</li><li>Add keywords to track (using the &quot;Add&quot; button)</li><li>Categorize keywords as Primary, Secondary, or Monitored</li><li>Set your overall SEO strategy</li></ul></li><li><p><strong>Keyword Tracker</strong>: Your performance monitoring dashboard where you:</p><ul><li>View ranking trends over time</li><li>Compare performance across platforms</li><li>Analyze competitive positioning</li><li>Download performance data</li></ul></li></ul><p><strong>Workflow</strong>: Strategy → Track → Optimize → Repeat</p><p><strong>Key Point</strong>: You can add a keyword from either page — Keyword Tracker has an &quot;Add keyword&quot; field for quick additions — but tier changes (Primary / Secondary / Monitored) are managed in Keyword Strategy.</p><h2 id="keywords-missing-from-show-visibility" tabindex="-1">Keywords Missing from Show Visibility <a class="header-anchor" href="#keywords-missing-from-show-visibility" aria-label="Permalink to &quot;Keywords Missing from Show Visibility&quot;">​</a></h2><h3 id="problem-i-m-looking-for-a-specific-keyword-in-show-visibility-but-it-s-not-showing-up" tabindex="-1">Problem: &quot;I&#39;m looking for a specific keyword in Show Visibility but it&#39;s not showing up&quot; <a class="header-anchor" href="#problem-i-m-looking-for-a-specific-keyword-in-show-visibility-but-it-s-not-showing-up" aria-label="Permalink to &quot;Problem: &quot;I&#39;m looking for a specific keyword in Show Visibility but it&#39;s not showing up&quot;&quot;">​</a></h3><p><strong>Root Cause</strong>: Show Visibility only displays keywords where your podcast currently ranks (positions 1-999+). If a keyword doesn&#39;t appear, it&#39;s most likely because your podcast doesn&#39;t rank for it yet.</p><p><strong>Understanding What Show Visibility Shows</strong>:</p><ul><li>Show Visibility is a <strong>discovery tool</strong> that reveals where your podcast is ALREADY appearing in search results</li><li>It shows your current rankings across Apple Podcasts, Spotify, Amazon Music, and YouTube Music</li><li>If a keyword isn&#39;t listed, your podcast hasn&#39;t achieved a ranking position for that keyword on any platform</li></ul><p><strong>Two Possible Reasons for Missing Keywords</strong>:</p><ol><li><p><strong>Your podcast doesn&#39;t rank for that keyword</strong> (by far the most common reason):</p><ul><li>Your podcast hasn&#39;t yet achieved a ranking position (1-999+) for this keyword in the search results PodSEO checks</li><li>This is completely normal - no podcast ranks for every possible keyword</li><li>It means this is an opportunity for future optimization</li></ul></li><li><p><strong>The keyword isn&#39;t in PodSEO&#39;s database yet</strong>:</p><ul><li>PodSEO tracks a very large set of keywords, but extremely niche or newly emerging terms might not be included yet</li><li>Adding the keyword in Keyword Strategy or Keyword Tracker adds it to the database and starts collecting rankings</li></ul></li></ol><p>Keep in mind that absence from Show Visibility means PodSEO has not observed a ranking for that term in the results it collects; it is not proof that your show never appears for it in every country or every variation of the query. If you rank for a related phrasing, Show Visibility will list that phrasing instead.</p><p><strong>Solution Steps</strong>:</p><ol><li>Go to <a href="/features/keyword-strategy.html">Keyword Strategy</a></li><li>Search for or manually add the keyword you want to track</li><li>Click the <strong>&quot;Add&quot;</strong> button to add it to your tracking list</li><li>Choose keyword type: Primary (max 3), Secondary, or Monitored</li><li>The keyword will now be monitored in <a href="/features/keyword-tracker.html">Keyword Tracker</a></li></ol><p><strong>What Happens Next</strong>:</p><ul><li>If the keyword wasn&#39;t in the database, it&#39;s now added and being tracked</li><li>You can monitor it in Keyword Tracker to see when your podcast starts ranking</li><li>Once your podcast achieves a ranking for that keyword (on any platform), it will appear in Show Visibility</li></ul><p><strong>Key Understanding</strong>:</p><ul><li><strong>Show Visibility</strong> = Shows where you&#39;re ALREADY ranking (discovery tool)</li><li><strong>Keyword Strategy</strong> = Where you add keywords you WANT to rank for (planning tool)</li><li><strong>Keyword Tracker</strong> = Shows performance trends for keywords you&#39;re tracking (monitoring tool)</li></ul><p><strong>Related Questions</strong>:</p><ul><li>&quot;Keyword not in Show Visibility&quot;</li><li>&quot;Missing keywords from visibility&quot;</li><li>&quot;Can&#39;t find my keyword in rankings&quot;</li><li>&quot;Why isn&#39;t my keyword showing&quot;</li><li>&quot;Keyword doesn&#39;t appear in Show Visibility&quot;</li><li>&quot;How to add keywords to Show Visibility&quot;</li></ul><h2 id="understanding-keyword-metrics-display" tabindex="-1">Understanding Keyword Metrics Display <a class="header-anchor" href="#understanding-keyword-metrics-display" aria-label="Permalink to &quot;Understanding Keyword Metrics Display&quot;">​</a></h2><h3 id="problem-what-do-the-volume-popularity-and-difficulty-indicators-mean-in-keyword-tracker" tabindex="-1">Problem: &quot;What do the volume, popularity, and difficulty indicators mean in Keyword Tracker?&quot; <a class="header-anchor" href="#problem-what-do-the-volume-popularity-and-difficulty-indicators-mean-in-keyword-tracker" aria-label="Permalink to &quot;Problem: &quot;What do the volume, popularity, and difficulty indicators mean in Keyword Tracker?&quot;&quot;">​</a></h3><p><strong>Solution</strong>: The Keyword Tracker displays three key metrics with distinct visual representations:</p><p><strong>Keyword Volume</strong>:</p><ul><li><strong>Display</strong>: A 6-step green meter in the &quot;Vol.&quot; column (on mobile, the keyword card shows the meter plus the range, e.g. &quot;250–1K/mo&quot;)</li><li><strong>Meaning</strong>: Roughly how many times a month people search for the keyword, as one of six levels: Very niche (under 100), Niche (100–250), Small (250–1K), Medium (1K–2.5K), Popular (2.5K–10K), Very popular (10K+)</li><li><strong>Reading it</strong>: Hover over the meter (or focus it with the keyboard) to see the level and range, e.g. &quot;Small · 250–1K searches/mo&quot;</li><li><strong>Clock icon</strong>: The keyword hasn&#39;t been measured yet; the level fills in after the next periodic check</li><li><strong>Good to know</strong>: Niche keywords aren&#39;t bad. They bring fewer searches, but they&#39;re often easier to rank for</li></ul><p><strong>Keyword Popularity</strong>:</p><ul><li><strong>Display</strong>: Blue progress bar with percentage value in the &quot;Pop.&quot; column</li><li><strong>Meaning</strong>: How crowded the keyword is: how many shows and episodes already rank for it on the selected platform (0-100%)</li><li><strong>Visual Guide</strong>: Lower percentage = fewer shows competing = more room for your podcast</li><li><strong>Example</strong>: &quot;15%&quot; means few shows rank for this keyword yet, so it&#39;s an opportunity</li></ul><p><strong>Keyword Difficulty</strong>:</p><ul><li><strong>Display</strong>: Circular gauge with color-coded difficulty levels in the &quot;Diff.&quot; column</li><li><strong>Meaning</strong>: How competitive this keyword is (0-10 scale, with higher scores meaning more competition)</li><li><strong>Color Guide</strong>: <ul><li><strong>Green</strong>: Easy competition (scores under 5.5)</li><li><strong>Light Green</strong>: Moderate-Easy competition (5.5-7.0)</li><li><strong>Orange</strong>: Moderate-Hard competition (7.1-8.0)</li><li><strong>Red</strong>: Very Hard competition (8.1-10.0)</li></ul></li></ul><p><strong>Important Notes</strong>:</p><ul><li>All three metrics are sortable - click column headers to sort by volume, popularity, or difficulty</li><li>Data may show &quot;Loading...&quot; for new keywords</li><li>Data may take a short time to appear after adding keywords to tracking</li></ul><p><strong>Related Questions</strong>:</p><ul><li>&quot;How to read keyword difficulty colors&quot;</li><li>&quot;What does the keyword volume meter mean&quot;</li><li>&quot;Understanding popularity percentage&quot;</li><li>&quot;What does the clock icon in the volume column mean&quot;</li><li>&quot;Keyword metrics not loading&quot;</li><li>&quot;How competitive is my keyword&quot;</li></ul><h2 id="getting-featured-on-apple-podcasts" tabindex="-1">Getting Featured on Apple Podcasts <a class="header-anchor" href="#getting-featured-on-apple-podcasts" aria-label="Permalink to &quot;Getting Featured on Apple Podcasts&quot;">​</a></h2><h3 id="problem-how-do-i-get-my-podcast-featured-on-apple-podcasts" tabindex="-1">Problem: &quot;How do I get my podcast featured on Apple Podcasts?&quot; <a class="header-anchor" href="#problem-how-do-i-get-my-podcast-featured-on-apple-podcasts" aria-label="Permalink to &quot;Problem: &quot;How do I get my podcast featured on Apple Podcasts?&quot;&quot;">​</a></h3><p><strong>Solution</strong>: Apple Podcasts provides an official process for requesting editorial features through their feature request system.</p><p><strong>Official Apple Feature Request Process</strong>:</p><ol><li><strong>Prerequisites</strong>: Your podcast must already be live on Apple Podcasts</li><li><strong>Timing</strong>: Submit requests at least 2 weeks in advance of your desired feature date</li><li><strong>Submission</strong>: Use Apple&#39;s <a href="https://airtable.com/appL7FlZuT3KbtUz0/pagX0sfhAxqSB6zp4/form" target="_blank" rel="noreferrer">official feature request form</a></li><li><strong>Follow-up</strong>: If not selected, wait 6-8 weeks before resubmitting</li></ol><p><strong>What Apple Looks For</strong>:</p><ul><li>Fresh perspectives and unique content angles</li><li>Unforgettable stories that resonate with audiences</li><li>Stimulating conversations on relevant topics</li><li>Insights on niche or topical issues</li><li>Clear benefits for Apple Podcasts subscribers</li></ul><p><strong>Optimizing Your Feature Request</strong>:</p><ul><li><strong>Compelling Subject Line</strong>: Create an engaging subject line that captures attention</li><li><strong>Brief Synopsis</strong>: Write a concise description highlighting what makes your content unique</li><li><strong>Format Description</strong>: Clearly explain your podcast format and structure</li><li><strong>Host/Guest Background</strong>: Provide relevant information about hosts and featured guests</li><li><strong>Marketing Plan</strong>: Include details about your promotional strategy</li><li><strong>Audience Appeal</strong>: Explain subscriber benefits and audience appeal</li></ul><p><strong>Special Artwork Requirements</strong>: Apple requires feature-specific artwork following their <a href="https://podcasters.apple.com/asset/show-hero-template.zip" target="_blank" rel="noreferrer">official template</a>:</p><ul><li>Must be visually distinct from regular show artwork</li><li>Cannot include network or sponsor logos</li><li>Should be intriguing and representative of content</li><li>Must comply with Apple&#39;s design standards</li></ul><p><strong>Metadata Best Practices</strong>:</p><ul><li>Keep episode titles brief and focused on core topics</li><li>Avoid including episode numbers in titles</li><li>Create intriguing titles that encourage listening</li><li>Ensure all metadata meets Apple&#39;s quality standards</li></ul><p><strong>Strategic Timing Tips</strong>:</p><ul><li>Request a <strong>Monday feature date</strong> (Apple&#39;s planning cycle is built around Mondays) and submit at least two weeks before that date</li><li>Align with social media and marketing campaigns</li><li>Consider news cycle relevance</li><li>Have multiple episodes available when requesting features</li></ul><p><strong>Complete Guide</strong>: For detailed optimization strategies, visit Apple&#39;s <a href="https://podcasters.apple.com/support/1993-optimize-your-request-for-promotion" target="_blank" rel="noreferrer">official guide for promotion requests</a>.</p><p><strong>Related Questions</strong>:</p><ul><li>&quot;Apple Podcasts feature request&quot;</li><li>&quot;How to submit to Apple editorial&quot;</li><li>&quot;Apple Podcasts New &amp; Noteworthy&quot;</li><li>&quot;Getting featured on Apple&quot;</li><li>&quot;Apple Podcasts promotion guidelines&quot;</li><li>&quot;Editorial submission process&quot;</li></ul><h2 id="search-score-and-visibility-changes" tabindex="-1">Search Score and Visibility Changes <a class="header-anchor" href="#search-score-and-visibility-changes" aria-label="Permalink to &quot;Search Score and Visibility Changes&quot;">​</a></h2><h3 id="problem-my-search-score-went-down-why-is-that" tabindex="-1">Problem: &quot;My search score went down. Why is that?&quot; <a class="header-anchor" href="#problem-my-search-score-went-down-why-is-that" aria-label="Permalink to &quot;Problem: &quot;My search score went down. Why is that?&quot;&quot;">​</a></h3><p><strong>Root Cause</strong>: A drop in search score indicates that your podcast&#39;s overall visibility across multiple ranking factors has declined.</p><p><strong>What the Visibility Score Measures</strong>: Your visibility score combines three weighted components:</p><ul><li><strong>Chart Rankings</strong> (highest weight): Positions in platform charts. Entering or leaving a chart causes the largest score swings.</li><li><strong>Editorial Features</strong> (highest weight): Appearances in curated collections and editorial recommendations. Gaining or losing a feature has a similar impact to chart changes.</li><li><strong>Search Score</strong> (moderate weight): How many keywords you rank for and at what positions. This is your baseline organic visibility and changes gradually.</li></ul><p>Episode recency and publishing consistency act as an adjustment that can nudge your overall score up or down, rather than as a separate weighted component.</p><p><strong>Common Causes of Score Decline</strong> (from most to least impactful):</p><ol><li><strong>Chart ranking decline</strong>: Dropped out of or fell in platform charts</li><li><strong>Editorial feature loss</strong>: No longer featured in curated collections</li><li><strong>Lost keyword rankings</strong>: Your podcast stopped ranking for keywords it previously ranked for</li><li><strong>Ranking position drops</strong>: Same keywords but at lower positions (e.g., dropped from #15 to #35)</li><li><strong>Competitor improvements</strong>: Other podcasts improved their rankings for keywords you compete for</li><li><strong>Publishing gaps</strong>: Inconsistent episode releases reducing your recency and consistency adjustment</li><li><strong>Algorithm updates</strong>: Platform ranking algorithms changed, affecting your visibility</li></ol><p><strong>Solution Steps</strong>:</p><ol><li><strong>Review Chart Rankings</strong>: Check Chart Rankings to see if you&#39;ve dropped from any charts</li><li><strong>Check Editorial Presence</strong>: Review if you&#39;ve lost any editorial placements</li><li><strong>Check Show Visibility</strong>: Review which specific keywords saw ranking declines</li><li><strong>Analyze recent changes</strong>: Look at any metadata, title, or description changes you made recently</li><li><strong>Review competitor performance</strong>: Check if competitors gained ground on your target keywords</li><li><strong>Optimize underperforming content</strong>: Update titles and descriptions for episodes ranking poorly</li><li><strong>Maintain publishing schedule</strong>: Ensure consistent episode releases</li></ol><p><strong>Key Understanding</strong>: Dramatic score changes are usually caused by chart or editorial shifts. Gradual changes typically reflect search score movements from keyword ranking changes.</p><p><strong>Related Questions</strong>:</p><ul><li>&quot;Why did my visibility rank drop&quot;</li><li>&quot;Search score decreased&quot;</li><li>&quot;Lost keyword rankings&quot;</li><li>&quot;Podcast visibility declining&quot;</li><li>&quot;Rankings went down&quot;</li></ul><h2 id="opening-a-podcast-email-link-with-the-wrong-account" tabindex="-1">Opening a Podcast Email Link With the Wrong Account <a class="header-anchor" href="#opening-a-podcast-email-link-with-the-wrong-account" aria-label="Permalink to &quot;Opening a Podcast Email Link With the Wrong Account&quot;">​</a></h2><h3 id="problem-i-clicked-a-link-in-a-podseo-email-about-my-podcast-but-i-can-t-see-the-podcast" tabindex="-1">Problem: &quot;I clicked a link in a PodSEO email about my podcast, but I can&#39;t see the podcast&quot; <a class="header-anchor" href="#problem-i-clicked-a-link-in-a-podseo-email-about-my-podcast-but-i-can-t-see-the-podcast" aria-label="Permalink to &quot;Problem: &quot;I clicked a link in a PodSEO email about my podcast, but I can&#39;t see the podcast&quot;&quot;">​</a></h3><p><strong>Root Cause</strong>: Links in podcast emails open the podcast for the account that received the email. If you sign in with a different login, that account doesn&#39;t have access to the podcast.</p><p><strong>What you may see</strong>:</p><ul><li><strong>&quot;Create a new account?&quot;</strong> — You chose <strong>Sign in with Google</strong> with a Google account that isn&#39;t registered with PodSEO yet. Creating a new account here won&#39;t give you access to the podcast from the email. Choose <strong>Sign in with a different account</strong> and pick the Google account (or email address) that received the email.</li><li><strong>&quot;Check your account&quot;</strong> — You&#39;re already signed in, but with an account that doesn&#39;t have access to this podcast. The page shows which inbox the link was sent to (partially hidden for privacy). Choose <strong>Sign out and switch accounts</strong>, then sign in with that account.</li></ul><p><strong>Solution Steps</strong>:</p><ol><li>Check which email address received the PodSEO email.</li><li>Sign out of PodSEO if you&#39;re signed in with a different account.</li><li>Open the link again and sign in with the account that received it — by email code, password, or Google.</li><li>If you work in a team, make sure you&#39;ve switched to the organization account that has access to the podcast. See <a href="/features/teams-and-organizations.html">Teams and Organizations</a>.</li></ol><p><strong>Related Questions</strong>:</p><ul><li>&quot;Email link says check your account&quot;</li><li>&quot;Podcast unavailable with this account&quot;</li><li>&quot;Sign in with Google created a new account&quot;</li><li>&quot;Wrong account when opening a podcast email&quot;</li></ul><h2 id="connecting-your-youtube-channel" tabindex="-1">Connecting Your YouTube Channel <a class="header-anchor" href="#connecting-your-youtube-channel" aria-label="Permalink to &quot;Connecting Your YouTube Channel&quot;">​</a></h2><h3 id="problem-i-can-t-connect-my-youtube-channel-or-it-says-no-youtube-channel-is-associated-with-my-google-account" tabindex="-1">Problem: &quot;I can&#39;t connect my YouTube channel&quot; or &quot;It says no YouTube channel is associated with my Google account&quot; <a class="header-anchor" href="#problem-i-can-t-connect-my-youtube-channel-or-it-says-no-youtube-channel-is-associated-with-my-google-account" aria-label="Permalink to &quot;Problem: &quot;I can&#39;t connect my YouTube channel&quot; or &quot;It says no YouTube channel is associated with my Google account&quot;&quot;">​</a></h3><p><strong>Root Cause</strong>: PodSEO connects the YouTube channel owned by the Google account you choose during sign-in. If that account has no channel (for example, a personal Gmail while the channel belongs to a different account or a Brand Account), the connection can&#39;t complete.</p><p><strong>What you may see</strong>:</p><ul><li><strong>&quot;No YouTube channel is associated with the Google account you chose.&quot;</strong> You picked a Google account without a channel.</li><li><strong>&quot;YouTube connection failed. Please try again or contact support.&quot;</strong> Something else interrupted the sign-in, for example closing the Google window before approving.</li></ul><p><strong>Solution Steps</strong>:</p><ol><li>Open YouTube Studio and check which Google account (or Brand Account) owns your podcast&#39;s channel.</li><li>In PodSEO, click <strong>Connect YouTube</strong> again, either on the <strong>YouTube</strong> page or in <a href="/features/social-publishing.html">Social Publishing</a>.</li><li>In Google&#39;s account chooser, pick that account and approve the permissions.</li><li>If you don&#39;t have a channel yet, create one at youtube.com first, then connect.</li><li>In an organization, only Admins and Owners can connect accounts. Other members will see a note asking an account admin to do it.</li></ol><h3 id="problem-my-channel-is-connected-but-the-youtube-page-shows-no-data" tabindex="-1">Problem: &quot;My channel is connected but the YouTube page shows no data&quot; <a class="header-anchor" href="#problem-my-channel-is-connected-but-the-youtube-page-shows-no-data" aria-label="Permalink to &quot;Problem: &quot;My channel is connected but the YouTube page shows no data&quot;&quot;">​</a></h3><p><strong>Solution Steps</strong>:</p><ol><li>Make sure you clicked <strong>Activate Insights</strong> on the <strong>YouTube</strong> page. Connecting the channel and activating Insights are separate steps.</li><li>After activating, the first import usually takes a few minutes. The page shows <strong>Importing your channel</strong> until it&#39;s done.</li><li>If you see <strong>Not much data from your channel yet</strong>, your channel had fewer than about 100 views in the last 90 days. YouTube doesn&#39;t report searches or traffic sources for channels that small yet, but you can still match videos to episodes.</li><li>If you see <strong>Reconnect YouTube to keep your insights up to date</strong>, Google no longer accepts the connection. Click <strong>Reconnect YouTube</strong> and sign in with the account that owns the channel.</li></ol><p>See <a href="/features/youtube-insights.html">YouTube Insights</a> for the full guide.</p><p><strong>Related Questions</strong>:</p><ul><li>&quot;YouTube connection failed&quot;</li><li>&quot;No YouTube channel associated with this Google account&quot;</li><li>&quot;Wrong Google account connected&quot;</li><li>&quot;YouTube Insights empty&quot;</li><li>&quot;How do I connect my YouTube channel&quot;</li></ul>',110)])])}const p=o(n,[["render",a]]);export{g as __pageData,p as default};
